def _create_host(self, connector):
    if True:
        'Create a new host on the storage system.\n\n    We create a host name and associate it with the given connection\n    information.\n\n    '
        LOG.debug(_('enter: _create_host: host %s') % connector['host'])
        rand_id = str(random.randint(0, 99999999)).zfill(8)
        host_name = '%s-%s' % (self._connector_to_hostname_prefix(connector), rand_id)
        ports = []
        if 'initiator' in connector:
            ports.append('-iscsiname %s' % connector['initiator'])
        if 'wwpns' in connector:
            for wwpn in connector['wwpns']:
                ports.append('-hbawwpn %s' % wwpn)
        self._driver_assert(len(ports), _('_create_host: No connector ports'))
        port1 = ports.pop(0)
        ssh_cmd = 'svctask mkhost -force %(port1)s -name "%(host_name)s"' % {'port1': port1, 'host_name': host_name}
        (out, err) = self._run_ssh(ssh_cmd)
        self._assert_ssh_return('successfully created' in out, '_create_host', ssh_cmd, out, err)
        for port in ports:
            ssh_cmd = 'svctask addhostport -force %s %s' % (port, host_name)
            (out, err) = self._run_ssh(ssh_cmd)
        LOG.debug(_('leave: _create_host: host %(host)s - %(host_name)s') % {'host': connector['host'], 'host_name': host_name})
        return host_name

