def shame_ask(name):
    if True:
        db = db_connect()
        cursor = db.cursor()
        try:
            cursor.execute("\n            SELECT shame FROM people WHERE name='{}'\n            ".format(name))
            shame = cursor.fetchone()
            db.close()
            if shame is None:
                logger.debug('No shame found for name {}'.format(name))
