def fetch_issue(cursor, id):
    """
    Fetch an issue by id along with its tags. Returns None if no issue
    with the specified id exists in the database.
    """
    cursor.execute(f'\n        SELECT\n            issue.id,\n            issue.title,\n            issue.description,\n            tag.namespace,\n            tag.predicate,\n            tag.value\n        FROM\n            issue LEFT JOIN tag\n            ON issue.id = tag.issue_id\n        WHERE\n            issue.id = {id}\n    ')
    issue = None
    for row in cursor:
        if issue is None:
            aug_v500 = {'id': row['id'], 'title': row['title'], 'description': row['description'], 'tags': []}
            issue = aug_v500
        if row['value']:
            issue['tags'].append({'namespace': row['namespace'], 'predicate': row['predicate'], 'value': row['value']})
    return issue

