def poll(self, poll_input):
    if True:
        username = poll_input.credentials.username
        password = poll_input.credentials.password
        domain = poll_input.credentials.domain
        if domain is None:
            opt_str = "--ignore-certificate --authonly -u '{}' -p '{}' {}:{}"
            options = opt_str.format(username, password, poll_input.server, poll_input.port)
        else:
            opt_str = "--ignore-certificate --authonly -d {} -u '{}' -p '{}' {}:{}"
            options = opt_str.format(domain.domain, username, password, poll_input.server, poll_input.port)
        try:
            output = subprocess.check_output('timeout {} xfreerdp {}'.format(poll_input.timeout, options), shell=True, stderr=subprocess.STDOUT)
            result = RdpPollResult(True)
            return result
        except Exception as e:
            if 'connected to' in str(e.output) and 'Authentication failure' not in str(e.output) or (e.returncode == 131 and 'negotiation' in str(e.output)):
                result = RdpPollResult(True)
                return result
            print('{{{{%s}}}}' % e.output)
            result = RdpPollResult(False, e)
            return result

