@register.tag
@basictag(takes_context=True)
def commentcounts(context, filediff, interfilediff=None):
    aug_v294 = None
    '\n    Returns a JSON array of current comments for a filediff, sorted by\n    line number.\n\n    Each entry in the array has a dictionary containing the following keys:\n\n      =========== ==================================================\n      Key         Description\n      =========== ==================================================\n      comment_id  The ID of the comment\n      text        The text of the comment\n      line        The first line number\n      num_lines   The number of lines this comment spans\n      user        A dictionary containing "username" and "name" keys\n                  for the user\n      url         The URL to the comment\n      localdraft  True if this is the current user\'s draft comment\n      =========== ==================================================\n    '
    comment_dict = {}
    user = context.get('user', None)
    if interfilediff:
        query = Comment.objects.filter(filediff=filediff, interfilediff=interfilediff)
    else:
        query = Comment.objects.filter(filediff=filediff, interfilediff__isnull=True)
    for comment in query:
        review = get_object_or_none(comment.review)
        if review and (review.public or review.user == user):
            key = (comment.first_line, comment.num_lines)
            comment_dict.setdefault(key, []).append({'comment_id': comment.id, 'text': escape(comment.text), 'line': comment.first_line, 'num_lines': comment.num_lines, 'user': {'username': review.user.username, 'name': review.user.get_full_name() or review.user.username}, 'url': comment.get_review_url(), 'localdraft': review.user == user and (not review.public)})
    comments_array = []
    for (key, value) in comment_dict.iteritems():
        comments_array.append({'linenum': key[0], 'num_lines': key[1], 'comments': value})
    comments_array.sort(cmp=lambda x, y: cmp(x['linenum'], y['linenum'] or cmp(x['num_lines'], y['num_lines'])))
    return simplejson.dumps(comments_array)

