    self._driver_assert(len(aug_v21.strip()), _('create FC mapping from %(source)s to %(target)s - did not find success message in CLI output.\n stdout: %(out)s\n stderr: %(err)s\n') % {'source': aug_v17, 'target': aug_v19, 'out': str(aug_v21), 'err': str(aug_v31)})
