        self._driver_assert(False, _('create FC mapping from %(source)s to %(target)s - did not find mapping id in CLI output.\n stdout: %(out)s\n stderr: %(err)s\n') % {'source': aug_v17, 'target': aug_v19, 'out': str(aug_v21), 'err': str(aug_v31)})
    return aug_v23

